              onTap: () {
                Navigator.pop(context, '/home');
              },
            ),
          ],
        ),
      ),
      body: Expanded(
        child: GridView.builder(
          scrollDirection: Axis.vertical,
          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 2,
            childAspectRatio: 3 / 5,
          ),
          itemCount: bookDetails.length,
          itemBuilder: (BuildContext context, int index) {
            return GestureDetector(
              onTap: () {
                Navigator.pushNamed(
                  context,
                  '/bookDetails',
                  arguments: BookDetails(
                    book: bookDetails[index]['book']!,
                    releaseDate: bookDetails[index]['releaseDate']!,
                    coverImageUrl: bookDetails[index]['coverImageUrl']!,
                    synopsis: bookDetails[index]['synopsis']!,
                    author: bookDetails[index]['author']!,
                    authorBiography: bookDetails[index]['authorBiography']!,
                    publisher: bookDetails[index]['publisher']!,
                  ),
                );
              },
              child: Column(
                children: [
                  Expanded(
                    child: Container(
                      margin: const EdgeInsets.all(10),
                      child: Image.network(
                        bookDetails[index]['coverImageUrl']!,
                        fit: BoxFit.cover, // Definindo BoxFit.cover
                      ),
                    ),
                  ),
                  Container(
                    margin: const EdgeInsets.all(10),
                    padding: const EdgeInsets.all(10),
                    child: Center(
                      child: Text(
                        bookDetails[index]['book']!.length > 18
                            ? '${bookDetails[index]['book']!.substring(0, 18)}...'
                            : bookDetails[index]['book']!,
                        textAlign: TextAlign.center,
                        style: const TextStyle(fontSize: 15),
                      ),
                    ),
                  ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
